/* CLICKHOUSE И OLAP-КУБЫ.
   ClickHouse — по HTTP-интерфейсу: POST с текстом запроса, ответ JSONCompact; параметры
   запроса — родные ClickHouse {имя:Тип}, значения берутся из клеток («год = B2»), поэтому
   в текст SQL ничего не подставляется и подмешать в запрос лишнее нельзя.
   OLAP — по XMLA (SOAP): Discover — каталоги, кубы, иерархии, уровни, меры; Execute — MDX.
   Отчёт: строки и столбцы — по иерархии, мера — в срезе; двойной щелчок по члену измерения
   раскрывает его детей (DrilldownMember) или сворачивает обратно.
   Сервер должен разрешать запросы со страницы (CORS): у ClickHouse это add_http_cors_header=1,
   у XMLA — настройка веб-сервера перед ним. */

/* ===== Поле на клетках листа: общий кусок игр магазина =====
   Строки и столбцы здесь — С НУЛЯ (r, c); адреса A1 считаются отсюда же.
   ячейка(строка, столбец) API плагина считает с единицы — поэтому везде «+ 1». */
const БУКВА = c => { let s = '', n = c + 1; while(n > 0){ const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = (n - 1 - m) / 26; } return s; };
const АДРЕС = (r, c) => БУКВА(c) + (r + 1);
const ОБЛАСТЬ = (r1, c1, r2, c2) => АДРЕС(r1, c1) + ':' + АДРЕС(r2, c2);
const клетка = (r, c) => ячейка(r + 1, c + 1);
/* Квадратные клетки: ширина столбца в знаках (знак — 7 точек), высота строки в пунктах (×4/3 точки). */
function клеткиКвадратом(r1, c1, r2, c2, точек){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(точек / 7);
  о.SetRowHeight(точек * 0.75);
}
/* Вернуть области обычные размеры клеток (столбец 92 точки, строка 24 точки = 18 пунктов). */
function обычныеРазмеры(r1, c1, r2, c2){
  const о = Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r1, c1, r2, c2));
  о.SetColumnWidth(92 / 7);
  о.SetRowHeight(18);
}
/* Ширина одного столбца и высота одной строки в точках экрана. */
function ширинаСтолбца(c, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(0, c, 0, c)).SetColumnWidth(точек / 7); }
function высотаСтроки(r, точек){ Api.GetActiveSheet().GetRange(ОБЛАСТЬ(r, 0, r, 0)).SetRowHeight(точек * 0.75); }
/* Приложение запоминает смещения строк и не сбрасывает их, когда плагин меняет высоты строк:
   после этого щелчок мыши попадает не в ту клетку. Пустая запись в далёкую пустую строку
   растит сетку листа, и смещения пересчитываются. Звать после смены высот. */
async function обновитьВысоты(){
  /* каждый раз — строка дальше прежней: сетка растёт, только если запись за её краем */
  let n = 0; try { n = +лист().память('высоты-шаг') || 0; } catch(e){}
  for(let k = n + 1; k <= n + 40; k++){
    const r = 5999 + k;
    let v = null;
    try { v = await клетка(r, 0).прочитать(); } catch(e){ continue; }
    if(v === null || v === undefined || v === ''){
      клетка(r, 0).значение = null;
      try { лист().запомнить('высоты-шаг', k); } catch(e){}
      return true;
    }
  }
  return false;
}
/* Курсор — на «стоянку» рядом с полем. Тогда повторный щелчок по той же клетке
   снова сменит выделение, и плагин получит событие: иначе второй щелчок молчал бы. */
function наСтоянку(r, c){ клетка(r, c).выделить(); }
/* Пуста ли область листа: игра не должна молча затирать чужие данные. */
async function областьПуста(r1, c1, r2, c2){
  const строки = await диапазон(ОБЛАСТЬ(r1, c1, r2, c2)).прочитать();
  for(const ряд of строки || []) for(const v of ряд || []) if(v !== null && v !== undefined && v !== '') return false;
  return true;
}
/* Рамка: все четыре стороны одним видом. */
const РАМКА = (вид, цвет) => ({в: {вид, цвет}, н: {вид, цвет}, л: {вид, цвет}, п: {вид, цвет}});
/* Число со словом в нужной форме: число(5, 'выстрел', 'выстрела', 'выстрелов') → «5 выстрелов». */
function число(n, одна, две, пять){ const a = Math.abs(n) % 100, b = a % 10;
  return n + ' ' + (a > 10 && a < 20 ? пять : b === 1 ? одна : b >= 2 && b <= 4 ? две : пять); }
/* Время «м:сс». */
const ВРЕМЯ = с => Math.floor(с / 60) + ':' + String(Math.floor(с % 60)).padStart(2, '0');
/* Повод события — клетка с нуля и на нужном ли листе. */
function гдеЩелчок(п, лист){
  if(!п || !п.адрес || (лист && п.лист !== лист)) return null;
  if(п.клеток > 1) return null;                     /* протянули мышью область — это не ход */
  return {r: п.строка - 1, c: п.столбец - 1};
}
/* Защита от «правой кнопки»: правый щелчок сначала зовёт меню, а через 150 мс
   приходит выделение той же клетки. Такой выбор ходом не считаем. */
let последнееМеню = {адрес: '', t: 0};
const этоПослеМеню = п => п && п.адрес === последнееМеню.адрес && Date.now() - последнееМеню.t < 1500;
/* ===== конец общего куска ===== */
/* Оформление области по клеткам. Api GetRange(…).SetNumberFormat и другие оформления области из потока
   задевают только ту часть, что была занята при запуске потока, — свежие строки остаются без оформления.
   л — лист плагина: лист(имя) или черновик; строки и столбцы — с нуля. */
function оформитьОбласть(л, r1, c1, r2, c2, стиль){
  if((r2 - r1 + 1) * (c2 - c1 + 1) > 300000) return false;
  for(let r = r1; r <= r2; r++) for(let c = c1; c <= c2; c++) л.ячейка(r + 1, c + 1).стиль = стиль;
  return true;
}

const ЗАГ = {b: 1, fill: '#eef3fe', гр: РАМКА('тонкая', '#9aa4b5'), valign: 'middle'};
const ЯЧ = {гр: РАМКА('тонкая', '#d5dae3')};
const НАЗВАНИЕ = {b: 1, size: 12, color: '#1f3b70'};
const ДЕНЬ = 86400000, ЭПОХА = Date.UTC(1899, 11, 30);
class Отказ extends Error {}
const отказ = т => { throw new Отказ(т); };
const номерСтолбца = б => { let c = 0; for(const ch of б.toUpperCase()) c = c * 26 + ch.charCodeAt(0) - 64; return c - 1; };
async function выполнить(ф){
  try { await ф(); }
  catch(e){ if(e instanceof Отказ) панель.сообщение(e.message); else { сообщить('ошибка: ' + (e && e.stack || e)); панель.сообщение('Не получилось: ' + (e && e.message || e)); } }
}
const первая = т => String(т || '').split('\n').map(s => s.trim()).filter(Boolean)[0] || '';
function якорьИз(текст){
  const т = String(текст || '').trim();
  if(!т){
    const в = книга.выделение;
    if(!в) отказ('Встаньте в клетку, откуда положить результат, или заполните «Куда».');
    return {лист: в.лист, r: в.r1 - 1, c: в.c1 - 1};
  }
  const м = /^(?:'?([^'!]+)'?!)?\$?([A-Za-z]{1,3})\$?(\d+)$/.exec(т);
  if(!м) отказ('«Куда» — адрес клетки: A1 или Лист2!A1.');
  const имя = м[1] || (книга.выделение ? книга.выделение.лист : книга.листы[0]);
  if(!книга.листы.includes(имя)) отказ('Нет листа «' + имя + '».');
  return {лист: имя, r: +м[3] - 1, c: номерСтолбца(м[2])};
}
const клеткаЛиста = (л, r, c) => лист(л).ячейка(r + 1, c + 1);
/* стереть прежнюю область отчёта: и значения, и оформление */
function стереть(л, о){
  if(!о) return;
  for(let r = о.r1; r <= о.r2; r++) for(let c = о.c1; c <= о.c2; c++){ const к = клеткаЛиста(л, r, c); к.значение = null; к.стиль = null; }
}
function ширины(л, c0, шир){
  шир.forEach((ш, j) => { try { Api.GetSheet(л).GetRange(ОБЛАСТЬ(0, c0 + j, 0, c0 + j)).SetColumnWidth(Math.max(60, Math.min(320, ш)) / 7); } catch(e){} });
}
const кодироватьФорму = о => Object.keys(о).filter(к => о[к] !== undefined && о[к] !== null && о[к] !== '').map(к => encodeURIComponent(к) + '=' + encodeURIComponent(о[к])).join('&');

/* ================= ClickHouse ================= */
/* Пароль по http (не https) уходит открытым текстом — говорим об этом один раз на адрес, но не
   мешаем: внутри сети заказчика ClickHouse часто отвечает по http. localhost не считаем. */
const предупреждёно = new Set();
function предупредитьОткрытыйКанал(адрес, сПаролем){
  if(!сПаролем || !/^http:\/\//i.test(адрес) || /^http:\/\/(localhost|127\.0\.0\.1|\[::1\])([:/]|$)/i.test(адрес) || предупреждёно.has(адрес)) return;
  предупреждёно.add(адрес);
  try { сообщить('Адрес ' + адрес + ' — http без шифрования: имя и пароль ClickHouse уходят по сети открытым текстом. Если сервер умеет https, впишите его.'); } catch(e){}
}
function chНастройки(){
  const п = параметры({});
  const адрес = String(п.chАдрес || '').trim().replace(/\/+$/, '');
  if(!/^https?:\/\//.test(адрес)) отказ('Адрес ClickHouse — вида http://сервер:8123.');
  let пароль = п.chПароль ? String(п.chПароль) : '';
  if(пароль && п.chЗапомнить) хранилище.тайно('chПароль', пароль);
  if(!пароль) пароль = хранилище.взять('chПароль', '') || '';
  return {адрес, база: String(п.chБаза || '').trim(), пользователь: String(п.chПользователь || '').trim(), пароль, лимит: Math.max(1, Math.min(1000000, Math.round(+п.chЛимит || 100000)))};
}
async function chЗапрос(sql, {параметры: пар = {}, лимит, настройки} = {}){
  const к = настройки || chНастройки();
  /* учётные данные — заголовками X-ClickHouse-User/Key, а не в строке запроса: строка запроса
     попадает в журналы прокси и веб-серверов и в историю, заголовки — нет (аудит S-03) */
  const ар = {database: к.база, default_format: 'JSONCompact', add_http_cors_header: 1,
    output_format_json_quote_64bit_integers: 0, max_result_rows: лимит, result_overflow_mode: лимит ? 'break' : undefined};
  for(const и in пар) ар['param_' + и] = пар[и];
  const заголовки = {'Content-Type': 'text/plain; charset=utf-8'};
  if(к.пользователь) заголовки['X-ClickHouse-User'] = к.пользователь;
  if(к.пароль) заголовки['X-ClickHouse-Key'] = к.пароль;
  предупредитьОткрытыйКанал(к.адрес, !!(к.пользователь || к.пароль));
  let о;
  try { о = await запрос(к.адрес + '/?' + кодироватьФорму(ар), {метод: 'POST', заголовки, тело: sql, срок: 300000}); }
  catch(e){ отказ('ClickHouse не ответил: ' + e.message + '. Проверьте адрес и что сервер разрешает запросы со страницы (add_http_cors_header).'); }
  if(!о.ок){
    const т = String(о.текст || '');
    const м = /DB::Exception:\s*([^\n]*)/.exec(т);
    отказ('ClickHouse: ' + (м ? м[1].replace(/\s*\(version [^)]*\)\s*$/, '').slice(0, 400) : первая(т).slice(0, 300) || 'код ' + о.код) + '.');
  }
  let т = о.тело;
  if(!т && о.текст && /^\s*\{/.test(о.текст)){ try { т = JSON.parse(о.текст); } catch(e){} }
  return т || null;
}
/* значение по типу ClickHouse → в клетку */
function видТипа(тип){
  let т = String(тип).trim();
  for(let i = 0; i < 5; i++){ const м = /^(?:Nullable|LowCardinality)\((.*)\)$/.exec(т); if(!м) break; т = м[1]; }
  if(/^(U?Int\d+|Float\d+|Decimal)/.test(т)) return 'число';
  if(/^Date(32)?$/.test(т)) return 'дата';
  if(/^DateTime/.test(т)) return 'время';
  if(/^Bool/.test(т)) return 'логика';
  return /^(Array|Map|Tuple|JSON|Object|Nested)/.test(т) ? 'json' : 'текст';
}
function вКлетку(v, вид){
  if(v === null || v === undefined) return null;
  if(вид === 'число'){ const n = typeof v === 'number' ? v : parseFloat(v); return Number.isFinite(n) ? n : String(v); }
  if(вид === 'дата' || вид === 'время'){
    const м = /^(\d{4})-(\d\d)-(\d\d)(?:[ T](\d\d):(\d\d):(\d\d)(\.\d+)?)?/.exec(String(v));
    if(!м) return String(v);
    const мс = Date.UTC(+м[1], +м[2] - 1, +м[3], +(м[4] || 0), +(м[5] || 0), +(м[6] || 0) + (м[7] ? +м[7] : 0));
    return (мс - ЭПОХА) / ДЕНЬ;
  }
  if(вид === 'логика') return v === true || v === 1 || v === 'true';
  if(вид === 'json') return typeof v === 'string' ? v : JSON.stringify(v);
  return String(v);
}
const ФОРМАТ_ВИДА = {дата: 'dd.mm.yyyy', время: 'dd.mm.yyyy hh:mm:ss'};
/* «год = B2», «регион = Лист2!C1», «вид = 'опт'» — значения параметров */
async function chПараметры(sql, текст){
  const нужны = new Map();
  String(sql).replace(/\{([A-Za-z_А-Яа-яЁё][\wА-Яа-яЁё]*)\s*:\s*([^}]+)\}/g, (_, и, т) => { нужны.set(и, т.trim()); return _; });
  const заданы = {};
  String(текст || '').split('\n').forEach(стр => { const м = /^\s*([^=\s]+)\s*=\s*(.*?)\s*$/.exec(стр); if(м) заданы[м[1]] = м[2]; });
  const итог = {};
  for(const [имя, тип] of нужны){
    if(!(имя in заданы)) отказ('Параметр {' + имя + ':' + тип + '} не задан: допишите в «Параметры» строку «' + имя + ' = B2» (адрес клетки или значение).');
    const с = заданы[имя];
    const адр = /^(?:'?([^'!]+)'?!)?\$?([A-Za-z]{1,3})\$?(\d+)$/.exec(с);
    let v;
    if(адр){
      const л = адр[1] || (книга.выделение ? книга.выделение.лист : книга.листы[0]);
      v = (await лист(л).прочитать(адр[2] + адр[3]))[0][0];
    } else v = с.replace(/^'(.*)'$/, '$1').replace(/^"(.*)"$/, '$1');
    const вид = видТипа(тип);
    if((вид === 'дата' || вид === 'время') && typeof v === 'number'){
      const д = new Date(ЭПОХА + Math.round(v * ДЕНЬ)), пд = x => String(x).padStart(2, '0');
      v = д.getUTCFullYear() + '-' + пд(д.getUTCMonth() + 1) + '-' + пд(д.getUTCDate()) + (вид === 'время' ? ' ' + пд(д.getUTCHours()) + ':' + пд(д.getUTCMinutes()) + ':' + пд(д.getUTCSeconds()) : '');
    }
    if(v === null || v === undefined || v === '') отказ('Параметр «' + имя + '» пуст: клетка ' + с + ' пустая.');
    итог[имя] = typeof v === 'boolean' ? (v ? 'true' : 'false') : String(v);
  }
  return итог;
}
const ПАМЯТЬ_CH = 'clickhouse-запросы';
function chЗапомненные(л){ let м = []; try { м = лист(л).память(ПАМЯТЬ_CH) || []; } catch(e){} return Array.isArray(м) ? м : []; }
/* выполнить и положить на лист; запрос запоминается при якоре — «Обновить» перевыполнит */
async function chНаЛист(з, настройки){
  const пар = await chПараметры(з.sql, з.параметры);
  const н = Object.assign({}, настройки, {база: з.база || настройки.база});
  const т = await chЗапрос(з.sql, {параметры: пар, лимит: з.лимит || н.лимит, настройки: н});
  const прежние = chЗапомненные(з.лист);
  const был = прежние.find(x => x.лист === з.лист && x.r === з.r && x.c === з.c);
  if(!т || !Array.isArray(т.meta)){
    return {строк: 0, столбцов: 0, без: true};
  }
  const мета = т.meta, данные = т.data || [], виды = мета.map(м => видТипа(м.type));
  const r0 = з.r, c0 = з.c, R = данные.length, C = мета.length;
  if(был && был.область) стереть(з.лист, был.область);
  /* шапка */
  мета.forEach((м, j) => { const к = клеткаЛиста(з.лист, r0, c0 + j); к.значение = м.name; к.стиль = ЗАГ; });
  /* строки: значения пачкой, оформление — по столбцам с датами */
  const строки = данные.map(ряд => ряд.map((v, j) => вКлетку(v, виды[j])));
  if(R) лист(з.лист).диапазон(ОБЛАСТЬ(r0 + 1, c0, r0 + R, c0 + C - 1)).записать(строки);
  виды.forEach((в, j) => { if(ФОРМАТ_ВИДА[в]) for(let i = 0; i < R; i++) клеткаЛиста(з.лист, r0 + 1 + i, c0 + j).стиль = {fmt: ФОРМАТ_ВИДА[в]}; });
  const шир = мета.map((м, j) => { let д = String(м.name).length; for(let i = 0; i < Math.min(R, 200); i++){ const v = данные[i][j]; д = Math.max(д, v == null ? 0 : String(v).length); } return д * 7.5 + 18; });
  ширины(з.лист, c0, шир);
  const запись = {лист: з.лист, r: r0, c: c0, sql: з.sql, параметры: з.параметры || '', база: н.база, лимит: з.лимит || н.лимит, область: {r1: r0, c1: c0, r2: r0 + R, c2: c0 + C - 1}, когда: new Date().toLocaleString('ru-RU')};
  const список = прежние.filter(x => !(x.лист === з.лист && x.r === з.r && x.c === з.c));
  список.push(запись);
  try { лист(з.лист).запомнить(ПАМЯТЬ_CH, список.slice(-30)); } catch(e){}
  const обрезано = т.rows_before_limit_at_least > R || (з.лимит || н.лимит) === R;
  return {строк: R, столбцов: C, обрезано, сек: т.statistics && т.statistics.elapsed};
}
async function chВыполнить(){
  const п = параметры({}), н = chНастройки();
  const sql = String(п.chSQL || '').trim().replace(/;\s*$/, '');
  if(!sql) отказ('Напишите запрос.');
  if(/\bFORMAT\s+\w+\s*$/i.test(sql)) отказ('Уберите FORMAT из запроса: плагин сам просит ответ в JSONCompact.');
  const я = якорьИз(п.chКуда);
  const р = await chНаЛист({лист: я.лист, r: я.r, c: я.c, sql, параметры: п.chПараметры, база: н.база}, н);
  if(р.без) панель.сообщение('Выполнено: запрос ничего не вернул (это была команда?).');
  else панель.сообщение('Положено в ' + я.лист + '!' + АДРЕС(я.r, я.c) + ': ' + число(р.строк, 'строка', 'строки', 'строк') + ' × ' + р.столбцов + (р.обрезано ? '. Достигнут предел строк — сузьте запрос или поднимите «Не больше строк»' : '') + (р.сек ? ' за ' + р.сек.toFixed(3).replace('.', ',') + ' с' : '') + '.');
}
async function chОбновить(){
  const н = chНастройки();
  const л = книга.выделение ? книга.выделение.лист : книга.листы[0];
