/* ================= XML: маленький разборщик (в потоке плагина нет DOMParser) ================= */
const СУЩНОСТИ = {lt: '<', gt: '>', amp: '&', quot: '"', apos: "'"};
const сущности = т => т.replace(/&(#x[0-9a-f]+|#\d+|\w+);/gi, (в, к) => к[0] === '#' ? String.fromCodePoint(к[1] === 'x' || к[1] === 'X' ? parseInt(к.slice(2), 16) : +к.slice(1)) : (СУЩНОСТИ[к] !== undefined ? СУЩНОСТИ[к] : в));
