function разобратьXML(т){
  const корень = {имя: '#', атр: {}, дети: [], текст: ''}, стек = [корень];
  const re = /<!\[CDATA\[([\s\S]*?)\]\]>|<!--[\s\S]*?-->|<\?[\s\S]*?\?>|<!DOCTYPE[^>]*>|<(\/?)([^\s>\/!?]+)((?:\s+[^\s=>\/]+\s*=\s*(?:"[^"]*"|'[^']*'))*)\s*(\/?)>|([^<]+)/g;
  let м;
  while((м = re.exec(т))){
    const верх = стек[стек.length - 1];
    if(м[1] !== undefined){ верх.текст += м[1]; continue; }
    if(м[6] !== undefined){ верх.текст += сущности(м[6]); continue; }
    if(м[3] === undefined) continue;
    if(м[2] === '/'){ if(стек.length > 1) стек.pop(); continue; }
    const узел = {имя: м[3].replace(/^.*:/, ''), атр: {}, дети: [], текст: ''};
    (м[4] || '').replace(/([^\s=]+)\s*=\s*(?:"([^"]*)"|'([^']*)')/g, (_, к, a, b) => { узел.атр[к.replace(/^.*:/, '')] = сущности(a !== undefined ? a : b); return _; });
    верх.дети.push(узел);
    if(!м[5]) стек.push(узел);
  }
  return корень;
}
